{
  "case_id": "xsu_sg_010_congenital_impairment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret gengiver listen korrekt som 'kan'-eksempler, men udelader at dokumentationen skal være lægefaglig og at en personlig redegørelse ikke erstatter det lægefaglige minimum. Det siger: 'Hvis der ikke er dokumentation tilgængelig, kan ansøgeren også inkludere en personlig redegørelse', hvilket kan læses som om redegørelsen træder i stedet for lægefaglig dokumentation. Det er en væsentlig upræcished i forhold til rubrikkens forbehold og SU-bekendtgørelsen § 37, stk. 1 og 3."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Sygehistorik, journalnotater, epikriser, støtteafgørelser/skånehensyn og personlig redegørelse er med. Svaret nævner ikke, at oplysningerne skal beskrive udrednings- og behandlingsforløb samt eventuelle aktuelle symptomer, og det mangler 'navnlig når forholdene ikke er dokumenteret'. Et kritisk element mangler derfor."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret er en liste over dokumentation, som ansøgeren kan indsende, og besvarer dermed spørgsmålet direkte."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret nævner ingen identificerbar kilde som lov, bestemmelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Indholdet svarer til vejledningens afsnit 4.3, og svaret tilføjer ingen ny regel, betingelse eller myndighed. Den tilføjede forklaring af 'epikriser' er rent definitorisk og ikke juridisk."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret mangler forbeholdene om, at eksemplerne ikke er kumulative krav, at de seneste foreliggende oplysninger kan være ældre, og at den personlige redegørelse kun supplerer og ikke ophæver det lægefaglige dokumentationsminimum. 'Kan' og 'også' antyder en vis ikke-obligatorisk karakter, men de krævede forbehold er ikke udtrykt."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er en enkel, intern konsistent opregning uden modstridende trin."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret bruger 'kan' om dokumentationen og 'kan også' om redegørelsen, hvilket svarer til vejledningens 'kan f.eks. være' og 'kan indgå'. Det gør ikke eksemplerne til absolutte krav."
    }
  },
  "xhaile_coverage": {
    "A49": {
      "label": "partial",
      "reason": "Svaret dækker sygehistorik, seneste journalnotater og den personlige redegørelse. Det forklarer ikke, hvad en medfødt funktionsnedsættelse er, nævner ikke eksemplerne på diagnoser og ikke, at medfødte tilfælde ofte mangler nyere dokumentation om aktuelt funktionsniveau."
    },
    "A35": {
      "label": "partial",
      "reason": "Svaret dækker de fleste dokumentationsformer og den personlige redegørelse som alternativ. Det udelader kravet om udrednings- og behandlingsforløb samt aktuelle symptomer, at oplysningerne skal være de seneste ved ansøgningstidspunktet, samt at listen ikke er udtømmende eller kumulativ."
    }
  },
  "overall_notes": "Svaret er kort og i det store og hele i overensstemmelse med vejledningens eksempler, men det angiver ingen kilde. Det mangler de centrale forbehold, især at den personlige redegørelse ikke erstatter det lægefaglige minimum, og beskrivelsen af udrednings- og behandlingsforløb og symptomer."
}

